                return "L"
            if r[-1] == node:
                return "R"
            return None

        # Build savings list deterministically
        savings = []
        for i in customers_all:
            for j in customers_all:
                if i == j:
                    continue
                # only compute once per unordered pair
        for i in customers_all:
            for j in customers_all:
                if j <= i:
                    continue
                s = matrix[i][depot] + matrix[depot][j] - matrix[i][j]
                # tie-breaker deterministic
                savings.append((s, i, j))
        savings.sort(key=lambda x: (-x[0], x[1], x[2]))

        for s, i, j in savings:
            ri = parent.get(i, None)
            rj = parent.get(j, None)
            if ri is None or rj is None or ri == rj:
                continue
            if load_map[ri] + load_map[rj] > capacity:
                continue
            ri_route = routes_map[ri]
            rj_route = routes_map[rj]
            ie = route_end_index(ri_route, i)
            je = route_end_index(rj_route, j)
            if ie is None or je is None:
                continue

            # Merge only if endpoints line up without internal node attachment
            # Cases:
            # ri: [ ... i ] (R) and rj: [ j ... ] (L) => ri + rj
            # ri: [ i ... ] (L) and rj: [ ... j ] (R) => reverse(ri) + reverse(rj)? Actually orientations:
            # We want i connected to j.
            if ie == "R" and je == "L":
                new_route = ri_route + rj_route
            elif ie == "L" and je == "R":
                new_route = list(reversed(ri_route)) + list(reversed(rj_route))
            elif ie == "R" and je == "R":
                # i at end, j at end => ri + reverse(rj)
                new_route = ri_route + list(reversed(rj_route))
            elif ie == "L" and je == "L":
                # i at start, j at start => reverse(ri) + rj
                new_route = list(reversed(ri_route)) + rj_route
            else:
                continue

            # Ensure endpoints connect as intended (already, but sanity):
            if not new_route or new_route[0] not in (i, j, ri_route[0], ri_route[-1], rj_route[0], rj_route[-1]):
                pass

            # Update structures: remove rj, keep ri
            for n in rj_route:
                parent[n] = ri
            routes_map[ri] = new_route
            load_map[ri] = load_map[ri] + load_map[rj]
            del routes_map[rj]
            del load_map[rj]

        routes_local = [routes_map[rid] for rid in list(routes_map.keys())]
        # Sort routes by first node for determinism
        routes_local.sort(key=lambda r: (r[0] if r else -1))
        return routes_local

    customers_all = set(instance["customer_ids"])
    if capacity is None or capacity <= 0:
        return []

    # Replay-aware: try incumbent-construct and a more exploitative savings start, then apply same local search.
    best_routes = None
    best_cost = None

    for constructor in (greedy_construct, clarke_wright_savings_construct):
        routes_try = constructor()
        if routes_try is None:
            continue
        routes_try = improve_routes(routes_try)
        if not feasible_routes(routes_try):
            continue
        c = 0
        for r in routes_try:
            c += route_cost(r)
        if best_cost is None or c < best_cost:
            best_cost = c
            best_routes = routes_try

    if best_routes is None:
        # Fall back to incumbent construction only (guarantees feasibility in normal cases)
        best_routes = improve_routes(greedy_construct())

    return best_routes
